      </AnfrageBuehne>

      <Weiterlesen
        text={w.weiter.text}
        items={[
          { href: pfad("/rechner/solarcarport"), icon: Calculator, ...w.weiter.items[0] },
          { href: pfad("/solarcarport"), icon: Car, ...w.weiter.items[1] },
